            left: 50%; /* Adjusted for 1-13 scale (Intensity ~12) */
        }

        .intensity-scale {
            display: flex;
            justify-content: space-between;
            font-size: 12px;
            margin-top: 5px;
        }

        /* Responsive Design */
        @media (max-width: 768px) {
            body {
                margin: 10px;
            }

            .table-container {
                padding: 10px;
            }

            table {
                font-size: 14px;
            }

            th, td {
                padding: 10px;
            }

            .intensity-bar {
                height: 15px;
            }

            .intensity-scale {
                font-size: 10px;
            }
        }

        @media (max-width: 480px) {
            table {
                font-size: 12px;
            }

            th, td {
                padding: 8px;
            }

            .intensity-bar {
                height: 12px;
            }

            .intensity-scale {
                font-size: 9px;
            }
        }





