.coffee-section h3 {
    font-size: 26px;
    margin-bottom: 5px;
    font-weight: 700;
  }
  .coffee-section h4 {
    margin-top: 0;
    font-size: 18px;
    font-weight: 600;
    color: #6b6b6b;
  }
  .coffee-section ul {
    list-style: none;
    padding: 0;
    margin: 20px 0;
  }
  .coffee-section ul li {
    display: flex;
    align-items: center;
    margin-bottom: 12px;
    font-size: 16px;
    font-weight: 500;
  }
  .coffee-section ul li img {
    width: 38px;
    margin-right: 10px;
  }

  .brew-steps {
    margin-top: 35px;
  }
  .brew-title {
    font-size: 22px;
    font-weight: 700;
    margin-bottom: 15px;
    border-bottom: 2px solid #eee;
    display: inline-block;
    padding-bottom: 4px;
  }
  .brew-step {
    display: flex;
    align-items: center;
    margin-bottom: 18px;
  }
  .brew-step img {
    width: 55px;
    height: auto;
    margin-right: 12px;
  }
  .brew-text {
    font-size: 16px;
    font-weight: 500;
    color: #333;
  }


